import { defineConfig } from "@playwright/test";
import baseConfig from "./playwright.config.js";

/**
 * Local pre-push profile: the full functional suite, minus the two things that
 * only make sense on the machine that owns their references.
 *
 * - `visual*` compares against `-linux` PNG baselines generated by CI. On a
 *   different GPU/font stack it reports 1–2% pixel drift, which is noise for a
 *   local run and costs time writing traces for every diff.
 * - `runtime-performance-baseline` asserts budget numbers; an uncontrolled
 *   laptop run cannot judge them.
 *
 * Everything else — behaviour, axe sweeps, the theme/locale matrix, PDF and
 * MIDI flows — still runs. CI keeps the unconditional full suite.
 */
export default defineConfig(baseConfig, {
  fullyParallel: true,
  workers: Number(process.env.GYS_E2E_WORKERS ?? 2),
  retries: 0,
  reporter: [["line"]],
  testIgnore: [
    "**/visual.spec.ts",
    "**/visual-reading.spec.ts",
    "**/visual-consistency-matrix.spec.ts",
    "**/runtime-performance-baseline.spec.ts",
  ],
});
